import{_ as t,c as o,o as i,al as a}from"./chunks/framework.CT7RwC5a.js";const _=JSON.parse('{"title":"Test MC_10 - Optical Flow / GPS Mixed","description":"","frontmatter":{},"headers":[],"relativePath":"en/test_cards/mc_10_optical_flow_gps_mixed.md","filePath":"en/test_cards/mc_10_optical_flow_gps_mixed.md"}'),l={name:"en/test_cards/mc_10_optical_flow_gps_mixed.md"};function r(n,e,s,p,c,d){return i(),o("div",null,e[0]||(e[0]=[a('<h1 id="test-mc-10-optical-flow-gps-mixed" tabindex="-1">Test MC_10 - Optical Flow / GPS Mixed <a class="header-anchor" href="#test-mc-10-optical-flow-gps-mixed" aria-label="Permalink to &quot;Test MC_10 - Optical Flow / GPS Mixed&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Test that optical flow mixed with GPS works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p><a href="./../sensor/optical_flow.html">Setup optical flow and GPS</a></p><p>Ensure there are no other sources of positioning besides optical flow</p><ul><li><a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>7</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#SYS_HAS_MAG">SYS_HAS_MAG</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_HGT_REF">EKF2_HGT_REF</a>: <code>1</code> (GPS)</li></ul><p>Ensure that the drone can go into <a href="./../flight_modes_mc/altitude.html">Altitude</a> / <a href="./../flight_modes_mc/position.html">Position</a> mode while still on the ground</p><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ <a href="./../flight_modes_mc/altitude.html">Altitude mode</a></p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ <a href="./../flight_modes_mc/position.html">Position mode</a></p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><p>❏ GPS Cutout</p><p>    ❏ Takeoff in position mode in GPS rich environment (outdoors)</p><p>    ❏ Open QGC and navigate to MAVLink Console</p><p>    ❏ Type <code>gps off</code> to disable GPS</p><p>    ❏ Drone should maintain position hold via optical flow</p><p>❏ GPS Degredation</p><p>    ❏ Takeoff in position mode in GPS rich environment (outdoors)</p><p>    ❏ Fly under a metal surface (or other GPS blocking structure)</p><p>    ❏ Ensure drone does not lose position hold or start drifting</p><p>    ❏ Fly out of metal structure to regain GPS</p><p>❏ GPS Acquisition</p><p>    ❏ Takeoff in position mode in non-GPS environment</p><p>    ❏ Fly into a GPS rich environment (outdoors)</p><p>    ❏ Ensure drone acquires GPS position</p><h2 id="expected-results" tabindex="-1">Expected Results <a class="header-anchor" href="#expected-results" aria-label="Permalink to &quot;Expected Results&quot;">​</a></h2><ul><li>Take-off should be smooth as throttle is raised</li><li>Drone should hold position within 1 meter in Position mode without pilot moving sticks</li><li>Drone should hold position in GPS rich environment as well as non-GPS environment</li><li>No oscillations should present in any of the above flight modes</li></ul>',34)]))}const m=t(l,[["render",r]]);export{_ as __pageData,m as default};
